<template><section><div class="flex justify-between mb-6"><h2 class="text-2xl font-bold">Thông báo</h2><button class="px-4 py-2 rounded bg-white/10" @click="readAll">Đánh dấu tất cả đã đọc</button></div><p v-if="error" class="text-error">{{error}}</p><p v-else-if="loading" class="text-gray-400">Đang tải…</p><div v-else-if="items.length===0" class="text-gray-400">Không có thông báo.</div><div v-else class="space-y-3"><article v-for="item in items" :key="item.notificationId" class="rounded-lg border border-white/10 p-4" :class="item.isRead?'bg-white/5':'bg-primary/10'"><div class="flex justify-between gap-4"><div><h3 class="font-semibold">{{item.title}}</h3><p class="mt-1 text-gray-300">{{item.content}}</p><p class="mt-2 text-sm text-gray-400">{{format(item.createdAt)}}</p></div><button v-if="!item.isRead" class="text-primary" @click="read(item)">Đã đọc</button></div></article></div></section></template><script setup>import{onMounted,ref}from'vue';import{adminApi}from'../../api/adminService';const items=ref([]),loading=ref(true),error=ref('');const load=async()=>{loading.value=true;try{items.value=(await adminApi.notifications()).data}catch(e){error.value=e.response?.data?.message||'Không thể tải thông báo.'}finally{loading.value=false}};const read=async(item)=>{try{item.isRead=(await adminApi.markRead(item.notificationId)).data.isRead}catch(e){error.value='Không thể cập nhật thông báo.'}};const readAll=async()=>{try{await adminApi.markAllRead();items.value.forEach(i=>i.isRead=true)}catch(e){error.value='Không thể cập nhật thông báo.'}};const format=v=>v?new Date(v).toLocaleString('vi-VN'):'';onMounted(load)</script>
